// its BEGIN body. `EXPLAIN` / `EXPLAIN QUERY PLAN` prefixes and the optional
// TEMP/TEMPORARY qualifier are all accepted.
const TRIGGER_PREFIX =
    /^\s*(?:EXPLAIN\s+(?:QUERY\s+PLAN\s+)?)?CREATE\s+(?:(?:TEMP|TEMPORARY)\s+)?TRIGGER\b/i;

const WORD_CHAR = /[A-Za-z0-9_]/;

/**
 * Splits a SQL string into an array of individual SQL statement strings.
 *
 * @param {string} sql - The SQL text to split.
 * @returns {string[]} The individual statements, each trimmed of surrounding
 *   whitespace. Trigger definitions are kept intact as a single element.
 */
export function splitStatements(sql) {
    const statements = [];
    let current = '';
    let inString = false;
    let stringChar = '';
    let word = '';

    // Trigger-body tracking. Once we're inside a trigger's BEGIN...END body,
    // semicolons no longer split statements. `blockDepth` counts nested
    // BEGIN/CASE ... END blocks so that a CASE expression inside the body does
    // not prematurely terminate the trigger.
    let inTriggerBody = false;
    let blockDepth = 0;

    const pushCurrent = () => {
        if (current.trim()) {
            statements.push(current.trim());
        }
        current = '';
    };

