                    // The trigger's BEGIN has been matched; the definition ends
                    // here. The following semicolon will finalize it.
                    inTriggerBody = false;
                    blockDepth = 0;
                }
            }
        } else if (upper === 'BEGIN' && TRIGGER_PREFIX.test(current)) {
            // This BEGIN opens the body of a CREATE TRIGGER statement.
            inTriggerBody = true;
            blockDepth = 1;
        }
    };

    for (let i = 0; i < sql.length; i++) {
        const char = sql[i];
        const nextChar = sql[i + 1];

        if (inString) {
            current += char;
            if (char === stringChar) {
                if (nextChar === stringChar) {
                    // Escaped quote (e.g. '' or "") — consume both.
                    current += nextChar;
                    i++;
                } else {
                    inString = false;
                }
            }
            continue;
