            inString = true;
            stringChar = char;
            current += char;
        } else if (char === '-' && nextChar === '-') {
            // Line comment — skip its contents but keep the terminating newline
            // so surrounding whitespace is preserved.
            i++; // skip second '-'
            while (i < sql.length && sql[i] !== '\n') {
                i++;
            }
            i--; // let the for-loop's i++ land back on the '\n' (or end)
        } else if (char === '/' && nextChar === '*') {
            // Block comment — skip everything up to and including `*/`.
            i++; // skip '*'
            while (i < sql.length - 1 && !(sql[i] === '*' && sql[i + 1] === '/')) {
                i++;
            }
            i++; // skip past closing '/'
        } else if (char === ';') {
            if (inTriggerBody) {
                // Semicolon inside a trigger body: part of the statement.
                current += char;
            } else {
                pushCurrent();
            }
        } else {
            current += char;
        }
    }

    flushWord();
    pushCurrent();

    return statements;
}

